  const html = samples.flatMap(s => Array.from({ length: n }, () => `<div class="label" style="width:${w}mm;height:${h}mm;padding:0">${labelHTML(cfg, s, 3.78)}</div>`)).join("");
  printHTML(title, html, { pageCss: `@page{size:${w}mm ${h}mm;margin:0}`, css: `.label-preview{border:none!important;box-shadow:none!important;border-radius:0!important}.label-preview{font-family:Arial,Helvetica,sans-serif}.label-preview svg{display:block;max-width:100%}.corner{position:absolute;top:0;left:0;right:0;height:1.2mm;background:#003080}.corner.red{background:#E00010}` });
